using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class YachtYardEdgeDetails {
const string D="Assets/Scenes/Oasis/YachtPortAtlas";static YachtYardEdgeDetails(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("YachtYardEdgeDetails.request"))return;File.Delete("YachtYardEdgeDetails.request");Run();}
class Geo{public List<Vector3> p=new List<Vector3>();public List<int> ids=new List<int>();public List<Vector4> tiles=new List<Vector4>();public List<Color> color=new List<Color>();public void Tri(Vector3 a,Vector3 b,Vector3 c,int tile,Color tint,float glow=0){int n=p.Count;p.AddRange(new[]{a,b,c});for(int i=0;i<3;i++){tiles.Add(new Vector4(tile,glow,0,0));color.Add(tint);}ids.AddRange(new[]{n,n+1,n+2});}public void Pole(Vector3 a,Vector3 b,float radius,int tile,Color tint,int sides=6,float glow=0){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var v=Vector3.Cross(axis,u);for(int k=0;k<sides;k++){float q=k*2*Mathf.PI/sides,r=(k+1)*2*Mathf.PI/sides;var o=u*Mathf.Cos(q)+v*Mathf.Sin(q);var n=u*Mathf.Cos(r)+v*Mathf.Sin(r);Tri(a+o*radius,b+o*radius,a+n*radius,tile,tint,glow);Tri(a+n*radius,b+o*radius,b+n*radius,tile,tint,glow);Tri(a,a+n*radius,a+o*radius,tile,tint,glow);Tri(b,b+o*radius,b+n*radius,tile,tint,glow);}}
public Mesh Save(Transform target){var mesh=new Mesh{name="Shared atlas yacht port perimeter details",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(p.Select(target.InverseTransformPoint).ToList());mesh.SetTriangles(ids,0);mesh.SetUVs(0,p.Select(v=>new Vector2(v.x*.5f,v.z*.5f)).ToList());mesh.SetUVs(1,tiles);mesh.SetColors(color);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=D+"/Meshes/Yacht Yard Perimeter Details.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){existing.Clear();existing.indexFormat=mesh.indexFormat;existing.vertices=mesh.vertices;existing.triangles=mesh.triangles;existing.normals=mesh.normals;existing.uv=mesh.uv;existing.SetUVs(1,tiles);existing.colors=mesh.colors;existing.RecalculateBounds();EditorUtility.SetDirty(existing);UnityEngine.Object.DestroyImmediate(mesh);return existing;}AssetDatabase.CreateAsset(mesh,path);return mesh;}}
class Edge{public Vector3 a,b;public int count;}
static string Key(Vector3 p)=>Mathf.RoundToInt(p.x*20)+","+Mathf.RoundToInt(p.y*20)+","+Mathf.RoundToInt(p.z*20);
static void Run(){try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var yard=roads.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Yatch_Port");var p=yard.sharedMesh.vertices.Select(yard.transform.TransformPoint).ToArray();var n=yard.sharedMesh.normals.Select(yard.transform.TransformDirection).ToArray();yard.sharedMesh.SetUVs(0,p.Select((v,i)=>Mathf.Abs(n[i].y)>.5f?new Vector2(v.x*.5f,v.z*.5f):Mathf.Abs(n[i].x)>Mathf.Abs(n[i].z)?new Vector2(v.z*.5f,v.y*.5f):new Vector2(v.x*.5f,v.y*.5f)).ToList());EditorUtility.SetDirty(yard.sharedMesh);var ids=yard.sharedMesh.triangles;var edges=new Dictionary<string,Edge>();var footprint=new List<Vector2[]>();for(int i=0;i<ids.Length;i+=3){int a=ids[i],b=ids[i+1],c=ids[i+2];if((n[a].y+n[b].y+n[c].y)/3<.7f||Mathf.Max(p[a].y,Mathf.Max(p[b].y,p[c].y))-Mathf.Min(p[a].y,Mathf.Min(p[b].y,p[c].y))>.15f)continue;footprint.Add(new[]{new Vector2(p[a].x,p[a].z),new Vector2(p[b].x,p[b].z),new Vector2(p[c].x,p[c].z)});for(int k=0;k<3;k++){var u=p[ids[i+k]];var v=p[ids[i+(k+1)%3]];string ku=Key(u),kv=Key(v),key=string.CompareOrdinal(ku,kv)<0?ku+"/"+kv:kv+"/"+ku;if(!edges.ContainsKey(key))edges[key]=new Edge{a=u,b=v};edges[key].count++;}}
var roadBounds=roads.GetComponentsInChildren<MeshRenderer>().Where(r=>r.sharedMaterial&&(r.sharedMaterial.name=="City PNG Markings"||r.sharedMaterial.name=="Road Atlas")).Select(r=>r.bounds).ToArray();Func<Vector2,bool> inside=point=>footprint.Any(tri=>{var a=tri[0];var b=tri[1];var c=tri[2];float den=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(den)<.001f)return false;float u=((b.y-c.y)*(point.x-c.x)+(c.x-b.x)*(point.y-c.y))/den;float v=((c.y-a.y)*(point.x-c.x)+(a.x-c.x)*(point.y-c.y))/den;return u>=-.0001f&&v>=-.0001f&&u+v<=1.0001f;});var old=yard.transform.Find("Yatch Port shared atlas details");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var geo=new Geo();int posts=0,bollards=0,lamps=0;foreach(var edge in edges.Values.Where(e=>e.count==1)){float length=Vector3.Distance(edge.a,edge.b);if(length<5)continue;var midpoint=new Vector2((edge.a.x+edge.b.x)*.5f,(edge.a.z+edge.b.z)*.5f);var direction=new Vector2(edge.b.x-edge.a.x,edge.b.z-edge.a.z).normalized;var normal=new Vector2(-direction.y,direction.x);if(inside(midpoint+normal*.6f)==inside(midpoint-normal*.6f))continue;int segments=Mathf.Max(1,Mathf.FloorToInt(length/8));for(int k=0;k<=segments;k++){var point=Vector3.Lerp(edge.a,edge.b,k/(float)segments);if(roadBounds.Any(b=>b.SqrDistance(new Vector3(point.x,b.center.y,point.z))<36))continue;geo.Pole(point+Vector3.up*.1f,point+Vector3.up*1.18f,.10f,0,Color.white);posts++;if(k<segments){var next=Vector3.Lerp(edge.a,edge.b,(k+1)/(float)segments);if(!roadBounds.Any(b=>b.SqrDistance(new Vector3(next.x,b.center.y,next.z))<36)){foreach(float h in new[]{.62f,1.03f}){var middle=(point+next)*.5f+Vector3.up*(h-.11f);geo.Pole(point+Vector3.up*h,middle,.035f,3,Color.white,4);geo.Pole(middle,next+Vector3.up*h,.035f,3,Color.white,4);}}}if(k%3==1){var dir=(edge.b-edge.a).normalized;var inwards=new Vector3(-dir.z,0,dir.x);var moor=point+inwards*.45f;geo.Pole(moor,moor+Vector3.up*.45f,.11f,2,Color.white);geo.Pole(moor+Vector3.up*.38f-dir*.23f,moor+Vector3.up*.38f+dir*.23f,.075f,2,Color.white);bollards++;}if(k%7==3){geo.Pole(point,point+Vector3.up*2.5f,.065f,2,Color.white);geo.Pole(point+Vector3.up*2.5f,point+Vector3.up*2.85f,.20f,-1,new Color(.9f,.86f,.74f),8,.8f);lamps++;}}}
var detail=new GameObject("Yatch Port shared atlas details");detail.transform.SetParent(yard.transform,false);detail.AddComponent<MeshFilter>().sharedMesh=geo.Save(yard.transform);detail.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared Yacht Yard Atlas.mat");var lod=detail.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.014f,new[]{detail.GetComponent<MeshRenderer>()})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAssetAndConnect(detail,D+"/Yatch Port Edge Details.prefab",InteractionMode.AutomatedAction);var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");var target=prefab.transform.Find(AnimationUtility.CalculateTransformPath(yard.transform,roads.transform));var oldSource=target.Find("Yatch Port shared atlas details");if(oldSource)UnityEngine.Object.DestroyImmediate(oldSource.gameObject);PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Yatch Port Edge Details.prefab"),target);PrefabUtility.SaveAsPrefabAsset(prefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(prefab);var standalone=UnityEngine.Object.Instantiate(yard.gameObject);standalone.name="Yatch_Port";PrefabUtility.SaveAsPrefabAsset(standalone,D+"/Yatch_Port Detailed.prefab");UnityEngine.Object.DestroyImmediate(standalone);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var center=yard.GetComponent<Renderer>().bounds.center;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,center+new Vector3(90,150,-120),center,"Yatch-Port-Shared-Atlas"});File.AppendAllText("FinalEnvironmentRoadReview/SharedYachtAtlasReport.txt","\nYARD DETAILS preserved yard mesh shape; corrected physical texture scale; perimeter posts="+posts+" bollards="+bollards+" lamps="+lamps+"; one shared atlas/material; reusable yard and nested detail prefabs saved; detail distance culling enabled.");}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/SharedYachtAtlasReport.txt","\nYARD FAILED "+e);Debug.LogException(e);}}
